mapper.select:
SELECT id, code, name, auth_json as authJson, platform_account as platformAccount, short_name as shortName, auth_status AS authStatus, auth_time AS authTime, update_time AS updateTime, update_user_name AS updateUserName, update_user_id AS updateUserId, is_product_sync as isProductSync, owner_code as ownerCode FROM overseas_provider WHERE ${params.sqlMap.default} and is_deleted = FALSE ORDER BY
${item.field} ${item.sort}
create_time DESC

SELECT opw.id as overseasProviderWarehouseId, op.short_name as platformShortName, opw.platform_warehouse_code, opw.platform_warehouse_name, opw.warehouse_id, opw.warehouse_name, opw.warehouse_code, opw.disabled FROM overseas_provider_warehouse as opw LEFT JOIN overseas_provider as op ON opw.main_id = op.id WHERE op.is_deleted = FALSE AND opw.is_deleted = FALSE
AND opw.id = #{params.overseasProviderWarehouseId}
AND opw.platform_warehouse_code = #{params.platformWarehouseCode}
AND op.short_name = #{params.platformShortName}
and op.code=#{params.code}
